// Dedicated renderer fixture; all package and automation operations remain in memory.
export default async function automationPluginScenarios(review) {
  await review.waitFor('window.__modelReview?.ready === true');
  await review.reducedMotion(true);
  await review.viewport(1440, 1000);
  await review.evaluate(`(() => {
    const fixture=window.__modelReview,bridge=window.piDesktop,clone=value=>structuredClone(value),cwd=fixture.snapshot.cwd;
    const state=window.__automationPlugins={checks:[],mutations:[],saves:[],cancels:[],failSave:true,previews:new Map()};
    const source='npm:fixture-review@1.0.0';
    state.catalog={cwd,projectTrusted:true,warnings:[],packages:[{source,scope:'user',name:'版本验证插件',description:'固定版本可修复安装；升级前先查看准确目标版本。',version:'1.0.0',installed:true,path:'C:/renderer-review/plugins/fixture-review'}],resources:[]};
    bridge.getPluginCatalog=async()=>clone(state.catalog);
    bridge.checkPluginUpdate=async request=>{
      state.checks.push(clone(request));if(state.failCheck)throw Error('版本目录暂时不可用');
      const target=request.latest?'2.1.0':'1.0.0',id='preview-'+state.checks.length;
      const result={id,cwd,scope:request.scope,source:request.source,installed:'1.0.0',constraint:'1.0.0',target,latest:'2.1.0',checkedAt:'2026-09-26T08:30:00Z',kind:request.latest?'upgrade':'repair',message:request.latest?'确认后安装此准确版本，并将此插件来源固定到该版本。':'重新安装指定版本以修复缺包；不会自动升级。',targetSource:'npm:fixture-review@'+target};
      state.previews.set(id,result);return clone(result);
    };
    bridge.mutatePlugin=async request=>{state.mutations.push(clone(request));const selected=state.previews.get(request.previewId);if(request.action!=='update-target'||!selected)throw Error('必须使用准确版本预览');if(state.failMutation)throw Error('模拟安装失败，尚未更改插件');state.catalog.packages[0].source=selected.targetSource;state.catalog.packages[0].version=selected.target;return clone(state.catalog);};
    const task={id:'active-plan',name:'受限项目巡检',prompt:'检查项目并报告变化',cwd,model:null,thinkingLevel:null,schedule:{kind:'interval',minutes:60},timeZone:'Asia/Shanghai',enabled:true,createdAt:'2026-09-20T00:00:00Z',updatedAt:'2026-09-26T00:00:00Z',nextRunAt:'2026-09-27T01:00:00Z',lastRunAt:'2026-09-26T01:00:00Z',scheduledRunCount:1,misfireGraceMinutes:30,maxScheduledRuns:3,dispatchRetryLimit:2};
    const run=(id,status,extra={})=>({id,automationId:task.id,name:task.name,cwd,trigger:'schedule',status,startedAt:'2026-09-26T01:00:00Z',finishedAt:status==='retrying'?null:'2026-09-26T01:01:00Z',sessionId:null,sessionPath:null,summary:'',error:null,attempts:1,scheduledAt:'2026-09-26T01:00:00Z',...extra});
    state.automations={revision:1,automations:[task,{...task,id:'completed-plan',name:'三次检查已完成',enabled:false,nextRunAt:null,scheduledRunCount:3,completedAt:'2026-09-26T01:01:00Z'}],runs:[run('retry-record','retrying',{attempts:2,retryAt:'2026-09-26T01:02:00Z',dispatchState:'not-started',error:'派发前连接暂时失败，尚未调用模型'}),run('skipped-record','skipped',{startedAt:'2026-09-25T01:00:00Z',summary:'超过补跑宽限，已跳过'}),run('completed-record','succeeded',{automationId:'completed-plan',name:'三次检查已完成',summary:'第三次检查完成',counted:true})]};
    bridge.getAutomationSnapshot=async()=>clone(state.automations);
    bridge.saveAutomation=async input=>{state.saves.push(clone(input));if(state.failSave)throw Error('模拟状态保存失败，原配置保留');Object.assign(state.automations.automations.find(task=>task.id===input.id),clone(input));state.automations.revision++;return clone(state.automations);};
    bridge.cancelAutomationRun=async id=>{state.cancels.push(id);Object.assign(state.automations.runs.find(run=>run.id===id),{status:'cancelled',finishedAt:'2026-09-26T01:03:00Z',retryAt:null,error:'任务已停止'});state.automations.revision++;return clone(state.automations);};
  })()`);
  await review.click('.pd-sidebar-plugins');
  await review.waitFor('Boolean(document.querySelector(".pd-plugin-card-main"))');
  await review.click('.pd-plugin-card-main');
  await review.clickText('.pd-plugin-update-check button','检查更新版本');
  await review.waitFor('Boolean(document.querySelector(".pd-plugin-update-preview"))');
  await review.assert('window.__automationPlugins.mutations.length===0 && window.__automationPlugins.checks[0].latest===false && document.querySelector(".pd-plugin-update-preview").textContent.includes("不会自动升级") && document.querySelector(".pd-plugin-update-preview code").textContent==="npm:fixture-review@1.0.0"','Fixed-version checks are read-only and show repair of the exact pinned version');
  await review.screenshot('plugin-fixed-version-repair');
  await review.clickText('.pd-plugin-update-preview button','确认修复 1.0.0');
  await review.waitFor('window.__automationPlugins.mutations.length===1 && !document.querySelector(".pd-plugin-update-preview")');
  await review.assert('window.__automationPlugins.mutations[0].previewId==="preview-1" && window.__automationPlugins.mutations[0].action==="update-target" && window.__automationPlugins.catalog.packages[0].version==="1.0.0"','Confirmed repair installs the checked target without upgrading');
  await review.assert('!document.querySelector(".pd-plugin-update-preview button.is-primary")','Successful fixed-version repair clears the consumed confirmation even when source and installed version are unchanged');
  await review.clickText('.pd-plugin-update-check button','检查更新版本');
  await review.waitFor('Boolean(document.querySelector(".pd-plugin-update-preview"))');
  await review.evaluate('window.__automationPlugins.failCheck=true');
  await review.clickText('.pd-plugin-update-preview button','查看最新版本 2.1.0');
  await review.waitFor('document.querySelector(".pd-plugin-update-check [role=alert]")?.textContent.includes("版本目录暂时不可用")');
  await review.assert('!document.querySelector(".pd-plugin-update-preview") && window.__automationPlugins.mutations.length===1','A failed version check cannot leave an older install target available');
  await review.evaluate('window.__automationPlugins.failCheck=false');
  await review.clickText('.pd-plugin-update-check button','检查更新版本');
  await review.waitFor('Boolean(document.querySelector(".pd-plugin-update-preview"))');
  await review.clickText('.pd-plugin-update-preview button','查看最新版本 2.1.0');
  await review.waitFor('document.querySelector(".pd-plugin-update-preview code")?.textContent==="npm:fixture-review@2.1.0"');
  await review.assert('window.__automationPlugins.checks.at(-1).latest===true && window.__automationPlugins.mutations.length===1','Preview latest is a separate read-only request before confirmation');
  await review.viewport(680, 800);
  await review.screenshot('plugin-latest-target-narrow');
  await review.assert('document.querySelector(".pd-plugin-update-preview").scrollWidth<=document.querySelector(".pd-plugin-update-preview").clientWidth+1 && document.documentElement.scrollWidth<=innerWidth','Exact target preview has no horizontal overflow at 680px');
  await review.evaluate('window.__automationPlugins.failMutation=true');
  await review.clickText('.pd-plugin-update-preview button','确认安装 2.1.0');
  await review.waitFor('document.querySelector(".pd-plugin-alert.is-error")?.textContent.includes("模拟安装失败") && !document.querySelector(".pd-plugin-update-preview button.is-primary").disabled');
  await review.assert('document.querySelector(".pd-plugin-update-preview code").textContent==="npm:fixture-review@2.1.0" && window.__automationPlugins.catalog.packages[0].version==="1.0.0"','Failed installation preserves its exact target for retry without reporting it as installed');
  await review.evaluate('window.__automationPlugins.failMutation=false');
  await review.clickText('.pd-plugin-update-preview button','确认安装 2.1.0');
  await review.waitFor('document.querySelector(".pd-plugin-card-meta")?.textContent.includes("2.1.0")');
  await review.assert('window.__automationPlugins.mutations[1].previewId==="preview-5" && window.__automationPlugins.mutations[2].previewId==="preview-5" && window.__automationPlugins.catalog.packages[0].source==="npm:fixture-review@2.1.0"','Upgrade confirmation and retry carry the exact preview identity and refreshed catalog shows its installed version');
  await review.viewport(1440,1000);
  await review.click('.pd-sidebar-automation');
  await review.waitFor('document.querySelectorAll(".pd-automation-card").length===2');
  await review.assert('document.querySelectorAll(".pd-automation-card")[1].textContent.includes("已完成") && document.querySelectorAll(".pd-automation-card")[1].textContent.includes("已计划派发 3 次 / 3") && document.querySelector(".pd-automation-card").textContent.includes("等待派发重试")','Automation cards expose completion, scheduled quota and retry status separately');
  await review.assert('(() => { const card=document.querySelectorAll(".pd-automation-card")[1],enable=[...card.querySelectorAll("footer button")].find(button=>button.textContent==="启用");return card.textContent.includes("编辑计划或提高次数上限") && !card.textContent.includes("已暂停后续计划") && enable.disabled && enable.title.includes("编辑计划") && !card.querySelector(".pd-automation-card-heading button").disabled; })()','Completed automations explain how to resume and keep editing available while direct enable is disabled');
  await review.screenshot('automation-quota-and-completion');
  await review.click('.pd-automation-card:first-child .pd-automation-card-heading button');
  await review.fill('.pd-automation-schedule-fields input[max="525600"]','90');
  await review.fill('.pd-automation-schedule-fields input[max="100000"]','4');
  await review.fill('.pd-automation-schedule-fields input[max="5"]','3');
  await review.viewport(900,720);
  await review.evaluate('document.querySelector(".pd-automation-form-body").scrollTop=document.querySelector(".pd-automation-form-body").scrollHeight');
  await review.screenshot('automation-safety-options-narrow');
  await review.assert('document.querySelector(".pd-automation-dialog").getBoundingClientRect().bottom<=innerHeight && document.querySelector(".pd-automation-form footer").getBoundingClientRect().bottom<=innerHeight && document.querySelector(".pd-automation-form-body").scrollWidth<=document.querySelector(".pd-automation-form-body").clientWidth+1','Narrow automation editor keeps the three reliability fields and save action usable');
  await review.click('.pd-automation-form button[type=submit]');
  await review.waitFor('document.querySelector(".pd-automation-error")?.textContent.includes("模拟状态保存失败")');
  await review.assert(`document.querySelector('input[max="525600"]').value==='90' && document.querySelector('input[max="100000"]').value==='4' && document.querySelector('input[max="5"]').value==='3'`,'Failed automation save preserves all reliability options');
  await review.evaluate('window.__automationPlugins.failSave=false');
  await review.click('.pd-automation-form button[type=submit]');
  await review.waitFor('!document.querySelector(".pd-automation-dialog")');
  await review.assert('window.__automationPlugins.saves.length===2 && window.__automationPlugins.saves.every(input=>input.misfireGraceMinutes===90&&input.maxScheduledRuns===4&&input.dispatchRetryLimit===3)','Grace, quota and bounded dispatch retries reach the save contract as numbers');
  await review.click('.pd-automation-card:first-child .pd-automation-card-title');
  await review.waitFor('Boolean(document.querySelector("[data-run-id=retry-record]"))');
  await review.fill('.pd-automation-history-filter select','retrying');
  await review.assert('document.querySelectorAll(".pd-automation-run").length===1 && document.querySelector("[data-run-id=retry-record]").textContent.includes("派发尝试 2 次") && document.querySelector("[data-run-id=retry-record]").textContent.includes("尚未调用模型")','Retry history exposes attempt count, scheduled occurrence and next retry without claiming execution');
  await review.viewport(680,720);
  await review.screenshot('automation-retry-history-narrow');
  await review.assert('document.querySelector(".pd-automation-history-dialog").getBoundingClientRect().right<=innerWidth && document.querySelector(".pd-automation-history-body").scrollWidth<=document.querySelector(".pd-automation-history-body").clientWidth+1','Retry history and stop action fit the 680px viewport');
  await review.click('[data-run-id=retry-record] .pd-automation-run-actions button');
  await review.waitFor('window.__automationPlugins.cancels.length===1');
  await review.assert('window.__automationPlugins.cancels[0]==="retry-record"','Stopping a pending retry targets the exact occurrence');
  await review.fill('.pd-automation-history-filter select','skipped');
  await review.assert('document.querySelector("[data-run-id=skipped-record]")?.textContent.includes("超过补跑宽限，已跳过")','Grace-expired occurrences have a distinct skipped history entry');
  await review.click('.pd-automation-history-dialog > header button');
  await review.click('.pd-automation-card:nth-child(2) .pd-automation-card-heading button');
  await review.fill('.pd-automation-schedule-fields input[max="100000"]','4');
  await review.click('.pd-automation-enable input');
  await review.click('.pd-automation-form button[type=submit]');
  await review.waitFor('!document.querySelector(".pd-automation-dialog")');
  await review.assert('window.__automationPlugins.saves.at(-1).id==="completed-plan" && window.__automationPlugins.saves.at(-1).maxScheduledRuns===4 && window.__automationPlugins.saves.at(-1).enabled===true','Completed automation can be edited to raise its limit and request continued scheduling');
}
